package com.fream.back.domain.faq.controller.command;

import com.fream.back.domain.faq.dto.InstantFaqRequestDto;
import com.fream.back.domain.faq.dto.FaqBidRequestDto;
import com.fream.back.domain.faq.exception.*;
import com.fream.back.domain.faq.service.command.FaqBidCommandService;
import com.fream.back.domain.notification.dto.NotificationRequestDto;
import com.fream.back.global.dto.ResponseDto;
import com.fream.back.global.utils.SecurityUtils;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;





@RestController
@RequestMapping("/order-bids")
@RequiredArgsConstructor
@Slf4j
@Validated
public class FaqBidCommandController {

    private final FaqBidCommandService orderBidCommandService;










    @PostMapping
    public ResponseEntity<ResponseDto<Long>> createOrderBid(@RequestBody @Valid FaqBidRequestDto requestDto) {

        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 생성");

        log.info("사용자 [{}]가 상품 사이즈(ID: {})에 대한 주문 입찰을 생성합니다. 입찰 가격: {}",
                email, requestDto.getProductSizeId(), requestDto.getBidPrice());


        Long orderBidId = orderBidCommandService.createOrderBid(
                email,
                requestDto.getProductSizeId(),
                requestDto.getBidPrice()
        ).getId();

        return ResponseEntity.ok(ResponseDto.success(orderBidId, "주문 입찰이 성공적으로 생성되었습니다."));
    }










    @DeleteMapping("/{orderBidId}")
    public ResponseEntity<ResponseDto<Void>> deleteOrderBid(@PathVariable("orderBidId") Long orderBidId) {

        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 삭제");

        log.info("사용자 [{}]가 주문 입찰(ID: {})의 삭제를 요청합니다.", email, orderBidId);


        orderBidCommandService.deleteOrderBid(orderBidId);

        return ResponseEntity.ok(ResponseDto.success(null, "주문 입찰이 성공적으로 삭제되었습니다."));
    }











    @PostMapping("/instant")
    public ResponseEntity<ResponseDto<Long>> createInstantOrderBid(@RequestBody @Valid InstantFaqRequestDto requestDto) {

        String email = SecurityUtils.extractAndValidateEmailForOrderBid("즉시 구매 입찰 생성");

        log.info("사용자 [{}]가 판매 입찰(ID: {})에 대한 즉시 구매를 요청합니다. 창고 보관 여부: {}",
                email, requestDto.getSaleBidId(), requestDto.isWarehouseStorage());


        NotificationRequestDto paymentRequest = enrichPaymentRequest(requestDto.getPaymentRequest(), email);


        Long orderId = orderBidCommandService.createInstantOrderBid(
                email,
                requestDto.getSaleBidId(),
                requestDto.getAddressId(),
                requestDto.isWarehouseStorage(),
                paymentRequest
        ).getId();

        return ResponseEntity.ok(ResponseDto.success(orderId, "즉시 구매가 성공적으로 처리되었습니다."));
    }








    private NotificationRequestDto enrichPaymentRequest(NotificationRequestDto paymentRequest, String email) {
        paymentRequest.setUserEmail(email);
        paymentRequest.setOrderId(null);
        return paymentRequest;
    }
}package com.fream.back.domain.faq.service.command;

import com.fream.back.domain.faq.entity.BidStatus;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.entity.FaqBid;
import com.fream.back.domain.faq.exception.*;
import com.fream.back.domain.faq.repository.FaqBidRepository;
import com.fream.back.domain.notification.dto.NotificationRequestDto;
import com.fream.back.domain.user.entity.UserSize;
import com.fream.back.domain.user.service.productSize.UserSizeQueryService;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.style.entity.StyleBid;
import com.fream.back.domain.style.service.query.StyleBidQueryService;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.query.ProductQueryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;




@Service
@RequiredArgsConstructor
@Slf4j
public class FaqBidCommandService {

    private final FaqBidRepository orderBidRepository;
    private final FaqCommandService orderCommandService;
    private final UserSizeQueryService productSizeQueryService;
    private final ProductQueryService userQueryService;
    private final StyleBidQueryService saleBidQueryService;












    @Transactional
    public FaqBid createOrderBid(String email, Long productSizeId, int bidPrice) {
        try {

            validateCreateOrderBidInput(email, productSizeId, bidPrice);


            Product user = userQueryService.findByEmail(email);


            UserSize productSize = productSizeQueryService.findById(productSizeId)
                    .orElseThrow(() -> new UserSizeNotFoundException("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));


            Faq order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);


            FaqBid orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "주문 입찰 생성");
            return null;
        }
    }




    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new FaqBidAccessDeniedException("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new UserSizeNotFoundException("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }




    private FaqBid createAndSaveOrderBid(Product user, UserSize productSize, int bidPrice, Faq order) {
        FaqBid orderBid = FaqBid.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .order(order)
                .build();


        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }














    @Transactional
    public FaqBid createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
                                          boolean isWarehouseStorage, NotificationRequestDto paymentRequest) {
        try {

            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);


            Product buyer = userQueryService.findByEmail(buyerEmail);


            StyleBid saleBid = getSaleBidAndValidate(saleBidId);
            Style sale = saleBid.getSale();


            Faq order = orderCommandService.createInstantOrder(
                    buyer,
                    saleBid,
                    addressId,
                    isWarehouseStorage,
                    paymentRequest
            );


            FaqBid orderBid = createInstantOrderBid(order, saleBid, sale);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
            return null;
        }
    }




    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, NotificationRequestDto paymentRequest) {
        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
            throw new FaqBidAccessDeniedException("구매자 이메일이 없습니다.");
        }
        if (saleBidId == null) {
            throw new StyleBidNotFoundException("판매 입찰 ID가 없습니다.");
        }
        if (addressId == null) {
            throw new InvalidFaqBidDataException("배송지 ID가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
        }
    }




    private StyleBid getSaleBidAndValidate(Long saleBidId) {
        StyleBid saleBid = saleBidQueryService.findById(saleBidId);
        if (saleBid == null) {
            throw new StyleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Style sale = saleBid.getSale();
        if (sale == null) {
            throw new InvalidFaqBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }




    private FaqBid createInstantOrderBid(Faq order, StyleBid saleBid, Style sale) {
        UserSize productSize = saleBid.getProductSize();

        FaqBid orderBid = FaqBid.builder()
                .user(order.getUser())
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(BidStatus.MATCHED)
                .order(order)
                .sale(sale)
                .build();


        orderBid.assignOrder(order);


        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }




    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof FaqException) {
            throw (FaqException) e;
        }
        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
        throw new FaqBidCreationFailedException(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
    }








    @Transactional
    public void matchOrderBid(FaqBid orderBid) {
        try {
            if (orderBid == null) {
                throw new FaqBidNotFoundException("주문 입찰 정보가 없습니다.");
            }

            if (orderBid.getStatus() == BidStatus.MATCHED) {
                throw new FaqBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
            }

            orderBid.updateStatus(BidStatus.MATCHED);
        } catch (Exception e) {
            if (e instanceof FaqException) {
                throw e;
            }
            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
            throw new FaqBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }









    @Transactional
    public void deleteOrderBid(Long orderBidId) {
        try {

            FaqBid orderBid = orderBidRepository.findById(orderBidId)
                    .orElseThrow(() -> new FaqBidNotFoundException("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));


            if (orderBid.getSale() != null) {
                throw new FaqBidAlreadyMatchedException("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
            }


            if (orderBid.getStatus() == BidStatus.MATCHED) {
                throw new FaqBidAlreadyMatchedException("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
            }


            if (orderBid.getOrder() != null) {
                orderCommandService.deleteOrder(orderBid.getOrder().getId());
            }


            orderBidRepository.delete(orderBid);
        } catch (Exception e) {
            if (e instanceof FaqException) {
                throw e;
            }
            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
            throw new FaqBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
}

